fn args(lua: &Lua, values: &[mlua::Value]) -> Table {
    let t = lua.create_table().unwrap();
    for (i, v) in values.iter().enumerate() {
        t.set(i + 1, v.clone()).unwrap();
    }
    t
}

fn rest(_lua: &Lua, values: &[mlua::Value]) -> mlua::MultiValue {
    values.iter().cloned().collect()
}

fn lua() -> Lua {
    Lua::new()
}

fn gen_host(none: bool, refuse: bool) -> GenHost {
    GenHost {
        lines: Mutex::new(Vec::new()),
        none,
        refuse,
    }
}

const MANIFEST_TEXT: &str = r#"
id = "ruby"
name = "Ruby"
version = "0.1.0"
api = "0.2"
side = "both"
capabilities = ["scripts"]
experimental = ["scripts"]
"#;

fn hmod(name: &str, files: &[(&str, &[u8])]) -> (std::path::PathBuf, std::path::PathBuf) {
    let dir = std::env::temp_dir().join(format!("horizon-lua-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("ruby.hmod");
    std::fs::write(
        &path,
        horizon_mods::Package::write_files(MANIFEST_TEXT, None, files).unwrap(),
    )
    .unwrap();
    (dir, path)
}

fn hmod_as(id: &str, files: &[(&str, &[u8])]) -> (std::path::PathBuf, std::path::PathBuf) {
    let dir = std::env::temp_dir().join(format!("horizon-lua-{}-{id}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("ruby.hmod");
    std::fs::write(
        &path,
        horizon_mods::Package::write_files(MANIFEST_TEXT, None, files).unwrap(),
    )
    .unwrap();
    (dir, path)
}

#[test]
fn remove_effect_is_generated_and_exact() {
    let lua = lua();
    let mut host = gen_host(false, false);
    let t = args(
        &lua,
        &[
            mlua::Value::String(
                lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                    .unwrap(),
            ),
            mlua::Value::String(lua.create_string("ruby:gen1").unwrap()),
        ],
    );
    run_generated_action(&mut host, "remove_effect", &t)
        .unwrap()
        .unwrap();
    assert_eq!(
        host.logged(),
        ["remove_effect 24249434048109030647017182301789831168 ruby:gen1"]
    );
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ghost").unwrap()),
                mlua::Value::String(lua.create_string("ruby:gen1").unwrap()),
            ],
        );
        run_generated_action(&mut host, "remove_effect", &t)
            .unwrap()
            .unwrap();
        assert!(
            host.logged().is_empty(),
            "an unresolvable player calls nothing"
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(
                    lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                        .unwrap(),
                ),
                mlua::Value::Table(lua.create_table().unwrap()),
            ],
        );
        let err = run_generated_action(&mut host, "remove_effect", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("remove_effect"), "{text}");
        assert!(text.contains("id"), "{text}");
    }
}

